param([ValidateSet('Admin','Sales','Inventory','Accounts')][string]$Role='Accounts',[ValidateSet('01','02','03')][string]$RunId='01')
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$credential=Import-Clixml -LiteralPath (Join-Path $root "server/.local/p27c/uat-$RunId-$Role.credential.clixml");$buffer=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($credential.Password)
try{Set-Clipboard -Value ([Runtime.InteropServices.Marshal]::PtrToStringBSTR($buffer));Write-Output "DEMO / SYNTHETIC only. URL: http://127.0.0.1:$(3106+[int]$RunId)/management";Write-Output "Username: $($credential.UserName). Password copied to your local clipboard; paste into the password field. It is never printed. Clear clipboard after signing in: Set-Clipboard -Value ''"}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($buffer)}
